//go:build ignore
package main
import("encoding/json";"fmt";"go/ast";"go/parser";"go/token";"math/rand";"os";"strconv";"github.com/xuri/nfp")
func main(){var formats []string;f,_:=parser.ParseFile(token.NewFileSet(),os.Getenv("WEKNORA_NFP_TEST_SOURCE"),nil,0);ast.Inspect(f,func(n ast.Node)bool{decl,ok:=n.(*ast.ValueSpec);if !ok{return true};for _,name:=range decl.Names{if name.Name=="testStrings"{outer:=decl.Values[0].(*ast.CompositeLit);for _,item:=range outer.Elts{row:=item.(*ast.CompositeLit);format,_:=strconv.Unquote(row.Elts[0].(*ast.BasicLit).Value);formats=append(formats,format)}}};return true});random:=rand.New(rand.NewSource(321));alphabet:=[]rune("#0?.012%[]$409xyz;:_*\\\"AMPSY通İß");for i:=0;i<4000;i++{var format []rune;for j:=0;j<random.Intn(28);j++{format=append(format,alphabet[random.Intn(len(alphabet))])};formats=append(formats,string(format))};var rows []any;for _,format:=range formats{func(){var sections []nfp.Section;panicMessage:="";func(){defer func(){if v:=recover();v!=nil{panicMessage=fmt.Sprint(v)}}();p:=nfp.NumberFormatParser();sections=p.Parse(format)}();rows=append(rows,map[string]any{"format":format,"sections":sections,"panic":panicMessage})}()};json.NewEncoder(os.Stdout).Encode(rows)}
